-- SCENTEASE initial schema. Empty database by design; no sample catalogue/customer/order data.
create extension if not exists pgcrypto;
create schema if not exists private;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path = '' as $$ select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin', false); $$;
grant usage on schema private to anon, authenticated;
grant execute on function private.is_admin() to anon, authenticated;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text not null default '',is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.brands(id uuid primary key default gen_random_uuid(),name text not null unique,description text not null default '',is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null default '',brand_id uuid references public.brands(id) on delete set null,category_id uuid references public.categories(id) on delete set null,price numeric(12,2) not null check(price>=0),compare_at_price numeric(12,2) check(compare_at_price is null or compare_at_price>=price),stock_quantity integer not null default 0 check(stock_quantity>=0),image_url text,sku text unique,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index products_active_created_idx on public.products(is_active,created_at desc);
create table public.cart_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,quantity integer not null check(quantity between 1 and 99),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,product_id));
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique,customer_id uuid not null references auth.users(id),customer_name text not null,customer_email text not null,phone text not null,shipping_address text not null,notes text not null default '',payment_method text not null default 'cod' check(payment_method='cod'),status text not null default 'pending' check(status in('pending','confirmed','processing','shipped','delivered','cancelled')),subtotal numeric(12,2) not null check(subtotal>=0),shipping_fee numeric(12,2) not null default 0 check(shipping_fee>=0),total numeric(12,2) not null check(total>=0),stock_restored_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,sku text,unit_price numeric(12,2) not null check(unit_price>=0),quantity integer not null check(quantity>0),line_total numeric(12,2) not null check(line_total>=0));
create table public.sales(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders(id) on delete restrict,amount numeric(12,2) not null check(amount>=0),recorded_at timestamptz not null default now());
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end; $$;
do $$ declare t text; begin foreach t in array array['profiles','categories','brands','products','cart_items','orders'] loop execute format('create trigger %I_updated before update on public.%I for each row execute function public.set_updated_at()',t,t);end loop;end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name,phone) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.raw_user_meta_data->>'phone','')) on conflict(id) do nothing;return new;end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.brands enable row level security;alter table public.products enable row level security;alter table public.cart_items enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.sales enable row level security;
create policy "profiles read self or admin" on public.profiles for select to authenticated using(id=(select auth.uid()) or private.is_admin());
create policy "profiles update self or admin" on public.profiles for update to authenticated using(id=(select auth.uid()) or private.is_admin()) with check(id=(select auth.uid()) or private.is_admin());
create policy "public read active categories" on public.categories for select to anon,authenticated using(is_active or private.is_admin());
create policy "admin manage categories" on public.categories for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy "public read active brands" on public.brands for select to anon,authenticated using(is_active or private.is_admin());
create policy "admin manage brands" on public.brands for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy "public read active products" on public.products for select to anon,authenticated using(is_active or private.is_admin());
create policy "admin manage products" on public.products for all to authenticated using(private.is_admin()) with check(private.is_admin());
create policy "cart owner read" on public.cart_items for select to authenticated using(user_id=(select auth.uid()) or private.is_admin());
create policy "cart owner insert" on public.cart_items for insert to authenticated with check(user_id=(select auth.uid()));
create policy "cart owner update" on public.cart_items for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "cart owner delete" on public.cart_items for delete to authenticated using(user_id=(select auth.uid()) or private.is_admin());
create policy "orders owner or admin read" on public.orders for select to authenticated using(customer_id=(select auth.uid()) or private.is_admin());
create policy "order items owner or admin read" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and(o.customer_id=(select auth.uid()) or private.is_admin())));
create policy "sales admin read" on public.sales for select to authenticated using(private.is_admin());
grant usage on schema public to anon,authenticated;grant select on public.categories,public.brands,public.products to anon,authenticated;grant select,insert,update,delete on public.cart_items to authenticated;grant select,update on public.profiles to authenticated;grant select on public.orders,public.order_items,public.sales to authenticated;grant insert,update,delete on public.categories,public.brands,public.products to authenticated;grant usage,select on all sequences in schema public to authenticated;
create or replace function public.checkout_cod(p_phone text,p_shipping_address text,p_notes text default '') returns uuid language plpgsql security definer set search_path='' as $$
declare v_uid uuid:=auth.uid();v_order_id uuid:=gen_random_uuid();v_name text;v_email text;v_subtotal numeric(12,2);v_order_number text:='SC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));r record;
begin if v_uid is null then raise exception 'Authentication required';end if;if nullif(trim(p_phone),'') is null or nullif(trim(p_shipping_address),'') is null then raise exception 'Phone and shipping address are required';end if;
select coalesce(p.full_name,''),u.email into v_name,v_email from auth.users u left join public.profiles p on p.id=u.id where u.id=v_uid;if nullif(trim(v_name),'') is null then v_name:=coalesce(v_email,'Customer');end if;
perform 1 from public.cart_items where user_id=v_uid for update;if not exists(select 1 from public.cart_items where user_id=v_uid) then raise exception 'Your cart is empty';end if;
if exists(select 1 from public.cart_items c join public.products p on p.id=c.product_id where c.user_id=v_uid and(not p.is_active or p.stock_quantity<c.quantity)) then raise exception 'One or more products are unavailable or have insufficient stock';end if;
select sum(p.price*c.quantity) into v_subtotal from public.cart_items c join public.products p on p.id=c.product_id where c.user_id=v_uid;
insert into public.orders(id,order_number,customer_id,customer_name,customer_email,phone,shipping_address,notes,subtotal,shipping_fee,total) values(v_order_id,v_order_number,v_uid,v_name,coalesce(v_email,''),trim(p_phone),trim(p_shipping_address),coalesce(p_notes,''),v_subtotal,0,v_subtotal);
for r in select p.id,p.name,p.sku,p.price,c.quantity from public.cart_items c join public.products p on p.id=c.product_id where c.user_id=v_uid for update of p loop update public.products set stock_quantity=stock_quantity-r.quantity where id=r.id and stock_quantity>=r.quantity;if not found then raise exception 'Stock changed during checkout. Please retry';end if;insert into public.order_items(order_id,product_id,product_name,sku,unit_price,quantity,line_total) values(v_order_id,r.id,r.name,r.sku,r.price,r.quantity,r.price*r.quantity);end loop;
delete from public.cart_items where user_id=v_uid;return v_order_id;end; $$;
revoke all on function public.checkout_cod(text,text,text) from public,anon;grant execute on function public.checkout_cod(text,text,text) to authenticated;
create or replace function public.admin_set_order_status(p_order_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$ declare v_old text;v_restored timestamptz;begin if not private.is_admin() then raise exception 'Admin access required';end if;if p_status not in('pending','confirmed','processing','shipped','delivered','cancelled') then raise exception 'Invalid order status';end if;select status,stock_restored_at into v_old,v_restored from public.orders where id=p_order_id for update;if not found then raise exception 'Order not found';end if;if v_old='cancelled' and p_status<>'cancelled' then raise exception 'Cancelled orders cannot be reopened';end if;if p_status='cancelled' and v_old<>'cancelled' and v_restored is null then update public.products p set stock_quantity=p.stock_quantity+oi.quantity from public.order_items oi where oi.order_id=p_order_id and oi.product_id=p.id;update public.orders set status='cancelled',stock_restored_at=now() where id=p_order_id;else update public.orders set status=p_status where id=p_order_id;end if;if p_status='delivered' then insert into public.sales(order_id,amount) select id,total from public.orders where id=p_order_id on conflict(order_id) do nothing;end if;end; $$;
revoke all on function public.admin_set_order_status(uuid,text) from public,anon;grant execute on function public.admin_set_order_status(uuid,text) to authenticated;
create or replace view public.admin_dashboard_stats with(security_invoker=true) as select(select count(*) from public.products) total_products,(select count(*) from public.profiles) total_customers,(select count(*) from public.orders) total_orders,(select count(*) from public.sales) total_sales_records,(select count(*) from public.orders where status='pending') pending_orders,(select coalesce(sum(amount),0) from public.sales) total_sales;grant select on public.admin_dashboard_stats to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "public view product images" on storage.objects for select to anon,authenticated using(bucket_id='product-images');
create policy "admin upload product images" on storage.objects for insert to authenticated with check(bucket_id='product-images' and private.is_admin());
create policy "admin update product images" on storage.objects for update to authenticated using(bucket_id='product-images' and private.is_admin()) with check(bucket_id='product-images' and private.is_admin());
create policy "admin delete product images" on storage.objects for delete to authenticated using(bucket_id='product-images' and private.is_admin());
do $$ begin alter publication supabase_realtime add table public.products;exception when duplicate_object then null;when undefined_object then null;end $$;
do $$ begin alter publication supabase_realtime add table public.orders;exception when duplicate_object then null;when undefined_object then null;end $$;
do $$ begin alter publication supabase_realtime add table public.cart_items;exception when duplicate_object then null;when undefined_object then null;end $$;